//! Golden-fixture tests against **real** Python Celery output.
//!
//! Every constant this file compares against lives in `tests/fixtures/` and was
//! recorded by `tests/python-compat/capture_fixtures.py` from a running Celery
//! publishing to a running Redis -- see `tests/fixtures/README.md` for the
//! versions and the capture command. Nothing here is generated by the code it
//! validates, which is the whole point: a test whose expected value comes out
//! of the function under test can only fail if that function contradicts
//! itself.
//!
//! Two directions are pinned:
//!
//! * **inbound** -- what Celery emits must parse into `celers-protocol` types
//!   with the right meaning, not merely without error;
//! * **outbound** -- what `create_python_celery_message` emits must equal
//!   `celers_envelope_accepted_by_celery.json`, which was written to disk only
//!   after an unmodified Celery worker executed it and returned `SUCCESS`.
//!
//! These run with no Redis and no Python. The live round trip that produced the
//! fixtures is `tests/python-compat`, driven from `python_interop.rs`.

use std::collections::HashMap;

use celers_protocol::compat::{
    create_python_celery_message, parse_python_message, python_args_repr, python_kwargs_repr,
    verify_message_format,
};
use celers_protocol::embed::EmbeddedBody;
use celers_protocol::result::{ResultMessage, TaskStatus};
use celers_protocol::Message;
use serde_json::{json, Value};
use uuid::Uuid;

// =============================================================================
// The captures
// =============================================================================

const POSITIONAL_LIST: &str = include_str!("fixtures/celery_task_v2_positional_list.json");
const POSITIONAL_TUPLE: &str = include_str!("fixtures/celery_task_v2_positional_tuple.json");
const KWARGS: &str = include_str!("fixtures/celery_task_v2_kwargs.json");
const COUNTDOWN: &str = include_str!("fixtures/celery_task_v2_countdown.json");
const ETA_EXPIRES: &str = include_str!("fixtures/celery_task_v2_eta_expires.json");
const CHAIN_HEAD: &str = include_str!("fixtures/celery_task_v2_chain_head.json");
const GROUP_MEMBER: &str = include_str!("fixtures/celery_task_v2_group_member.json");
const RESULT_SUCCESS: &str = include_str!("fixtures/celery_result_success.json");
const RESULT_FAILURE: &str = include_str!("fixtures/celery_result_failure.json");
const SAFEREPR_TABLE: &str = include_str!("fixtures/celery_saferepr_table.json");
const CELERS_ACCEPTED: &str = include_str!("fixtures/celers_envelope_accepted_by_celery.json");

/// Every task envelope Celery produced, by name.
fn task_fixtures() -> Vec<(&'static str, &'static str)> {
    vec![
        ("positional_list", POSITIONAL_LIST),
        ("positional_tuple", POSITIONAL_TUPLE),
        ("kwargs", KWARGS),
        ("countdown", COUNTDOWN),
        ("eta_expires", ETA_EXPIRES),
        ("chain_head", CHAIN_HEAD),
        ("group_member", GROUP_MEMBER),
    ]
}

fn parse(fixture: &str) -> Message {
    let value: Value = serde_json::from_str(fixture).expect("fixture is valid JSON");
    parse_python_message(value).expect("a real Celery envelope must parse")
}

fn body_of(fixture: &str) -> EmbeddedBody {
    EmbeddedBody::decode(&parse(fixture).body).expect("body is a protocol v2 tuple")
}

// =============================================================================
// Inbound: Celery -> CeleRS
// =============================================================================

/// Regression: this file used to build its "canonical Celery envelope" by
/// calling `create_python_celery_message` and then asserting over the result,
/// so it could only fail if that function contradicted itself. These fixtures
/// come from Celery.
#[test]
fn every_captured_celery_envelope_parses_and_validates() {
    for (name, fixture) in task_fixtures() {
        let message = parse(fixture);
        assert_eq!(message.headers.lang, "py", "{name}: Celery always says py");
        assert_eq!(message.content_type, "application/json", "{name}");
        assert_eq!(message.content_encoding, "utf-8", "{name}");
        assert_eq!(message.properties.delivery_mode, 2, "{name}");

        // The envelope CeleRS re-serializes from it is still a valid v2
        // envelope -- a parse that silently dropped `body_encoding` would be
        // caught here rather than by a Python worker in production.
        verify_message_format(&message)
            .unwrap_or_else(|e| panic!("{name}: re-serialized envelope is not valid v2: {e}"));

        // Celery frames the body as [args, kwargs, embed] in every case.
        let body = EmbeddedBody::decode(&message.body)
            .unwrap_or_else(|e| panic!("{name}: body is not a v2 tuple: {e}"));
        let _ = body.args;
    }
}

#[test]
fn positional_arguments_survive_the_wire() {
    let body = body_of(POSITIONAL_LIST);
    assert_eq!(body.args, vec![json!(4), json!(5)]);
    assert!(body.kwargs.is_empty());
    assert!(!body.embed.has_workflow());

    let message = parse(POSITIONAL_LIST);
    assert_eq!(message.headers.task, "tasks.add");
    // `apply_async(args=[4, 5])` keeps args a *list*, so Celery reprs a list.
    assert_eq!(message.headers.argsrepr(), Some("[4, 5]"));

    // `.delay(4, 5)` -- and `apply_async(args=(4, 5))` -- keep args a tuple,
    // which is the form CeleRS emits. Both are genuine Celery output.
    let tuple = parse(POSITIONAL_TUPLE);
    assert_eq!(tuple.headers.argsrepr(), Some("(4, 5)"));
    assert_eq!(body_of(POSITIONAL_TUPLE).args, vec![json!(4), json!(5)]);
}

#[test]
fn keyword_arguments_survive_the_wire() {
    let body = body_of(KWARGS);
    assert_eq!(body.args, vec![json!("Ada")]);
    assert_eq!(body.kwargs.get("loud"), Some(&json!(true)));
    assert_eq!(body.kwargs.get("punct"), Some(&json!("?")));

    // Celery renders Python literals here, not JSON: `True`, not `true`.
    let message = parse(KWARGS);
    let kwargsrepr = message.headers.kwargsrepr().expect("kwargsrepr is present");
    assert!(
        kwargsrepr.contains("True"),
        "Celery writes a Python bool in kwargsrepr, got {kwargsrepr:?}"
    );
    assert!(
        !kwargsrepr.contains("true"),
        "got JSON, not Python: {kwargsrepr:?}"
    );
}

#[test]
fn countdown_reaches_the_wire_as_an_eta_header() {
    // Celery resolves `countdown=30` client-side; the worker only ever sees an
    // absolute `eta`, so a CeleRS consumer that looked for `countdown` would
    // wait forever.
    let message = parse(COUNTDOWN);
    let eta = message.headers.eta.expect("countdown became an eta");
    assert!(
        message.headers.expires.is_none(),
        "countdown must not set expires"
    );
    assert!(
        eta.timestamp() > 1_700_000_000,
        "eta must be an absolute instant, got {eta}"
    );
}

#[test]
fn eta_and_expires_survive_the_wire() {
    let message = parse(ETA_EXPIRES);
    let eta = message.headers.eta.expect("eta is present");
    let expires = message.headers.expires.expect("expires is present");
    assert_eq!(eta.to_rfc3339(), "2030-01-02T03:04:05+00:00");
    assert_eq!(expires.to_rfc3339(), "2030-01-02T04:04:05+00:00");

    // kombu additionally stamps `properties.expiration` (milliseconds as a
    // string). CeleRS ignores it and reads the header, which is the field
    // Celery's own worker honours.
    let raw: Value = serde_json::from_str(ETA_EXPIRES).expect("json");
    assert!(
        raw["properties"]["expiration"].is_string(),
        "the capture should carry kombu's expiration property"
    );
}

#[test]
fn a_chain_head_carries_the_next_link_in_the_embed_dict() {
    let body = body_of(CHAIN_HEAD);
    assert_eq!(body.args, vec![json!(1), json!(2)]);
    assert!(body.embed.has_workflow(), "a chain head has a workflow");
    assert_eq!(
        body.embed
            .chain
            .iter()
            .map(|c| c.task.as_str())
            .collect::<Vec<_>>(),
        vec!["tasks.double"],
        "the second link travels inside the first message"
    );

    // Celery does *not* put the chain in a header; a consumer reading only
    // headers would run the first task and silently drop the rest.
    let raw: Value = serde_json::from_str(CHAIN_HEAD).expect("json");
    assert!(raw["headers"].get("chain").is_none());
}

#[test]
fn a_group_member_carries_the_group_id_and_index() {
    let message = parse(GROUP_MEMBER);
    assert!(
        message.headers.group.is_some(),
        "a group member names its group in the headers"
    );

    // `group_index` is a Celery 5.x header CeleRS has no typed field for; it
    // must survive into `extra` rather than being rejected as unknown.
    assert_eq!(
        message.headers.extra.get("group_index"),
        Some(&json!(0)),
        "group_index must reach the extra headers"
    );
}

/// Celery 5.6 writes four headers CeleRS has no typed field for. They must be
/// tolerated, and the ones with values must be readable.
#[test]
fn celery_5_6_only_headers_are_tolerated() {
    for (name, fixture) in task_fixtures() {
        let raw: Value = serde_json::from_str(fixture).expect("json");
        for header in [
            "group_index",
            "replaced_task_nesting",
            "stamped_headers",
            "stamps",
        ] {
            assert!(
                raw["headers"].get(header).is_some(),
                "{name}: the capture should contain {header}; re-capture the fixtures"
            );
        }
        // Parsing must not reject them...
        let message = parse(fixture);
        // ...and they must not be silently discarded either.
        assert_eq!(
            message.headers.extra.get("replaced_task_nesting"),
            Some(&json!(0)),
            "{name}: replaced_task_nesting must reach the extra headers"
        );
    }
}

// =============================================================================
// Inbound: Celery result records
// =============================================================================

#[test]
fn a_real_celery_success_record_parses() {
    let result = ResultMessage::from_json(RESULT_SUCCESS.as_bytes())
        .expect("a real Celery success record must parse");
    assert_eq!(result.status, TaskStatus::Success);
    assert!(result.is_success());
    assert_eq!(result.result, Some(json!(9)));
    assert!(result.traceback.is_none());
    assert!(result.date_done.is_some(), "Celery always stamps date_done");
}

#[test]
fn a_real_celery_failure_record_parses_into_the_typed_exception() {
    let result = ResultMessage::from_json(RESULT_FAILURE.as_bytes())
        .expect("a real Celery failure record must parse");
    assert_eq!(result.status, TaskStatus::Failure);
    assert!(result.is_failure());

    let exception = result
        .exception
        .as_ref()
        .expect("the exception dict in `result` must be lifted onto the typed field");
    assert_eq!(exception.exc_type, "ValueError");
    assert_eq!(exception.exc_module.as_deref(), Some("builtins"));

    // `traceback` is a sibling string, not part of the exception dict. Without
    // it a mixed-language cluster loses every Python stack trace.
    let traceback = result.traceback.as_deref().expect("traceback is present");
    assert!(
        traceback.starts_with("Traceback (most recent call last):"),
        "unexpected traceback: {traceback}"
    );
    assert!(
        traceback.contains("ValueError: fixture failure"),
        "the traceback must carry the raised exception: {traceback}"
    );
}

// =============================================================================
// Outbound: CeleRS -> Celery
// =============================================================================

/// The bytes in this fixture were executed by an unmodified Celery 5.6.3
/// worker, which returned `SUCCESS` with `result == 9`; only then were they
/// written to disk (see `capture_fixtures.py::capture_celers_acceptance`).
/// Asserting equality against them therefore asserts acceptance.
#[test]
fn the_canonical_celers_envelope_is_the_one_celery_accepted() {
    // The id `capture_fixtures.py` pinned for this envelope.
    let task_id: Uuid = "7b1a0d1e-0000-4000-8000-000000000012"
        .parse()
        .expect("fixture task id");
    let produced =
        create_python_celery_message("tasks.add", task_id, vec![json!(4), json!(5)], json!({}))
            .expect("the canonical envelope must serialize");

    let accepted: Value = serde_json::from_str(CELERS_ACCEPTED).expect("fixture is valid JSON");

    assert_eq!(
        produced, accepted,
        "create_python_celery_message no longer produces the envelope a real \
         Celery worker was proven to accept. Re-run `tests/python-compat/run.sh \
         capture` only after confirming the new bytes still execute."
    );

    // Byte shape, not just structural equality: `serde_json::Map` is ordered,
    // so both sides serialize their keys the same way and a reordering would
    // show up here.
    assert_eq!(
        serde_json::to_string(&produced).expect("serialize"),
        serde_json::to_string(&accepted).expect("serialize"),
        "the serialized bytes drifted from the accepted capture"
    );
}

/// The envelope CeleRS emits must also satisfy the structural checker, and
/// must round-trip back into a `Message` -- so `verify_message_format` and
/// the parser agree with the wire, not merely with each other.
#[test]
fn the_celers_envelope_round_trips_through_the_parser() {
    let accepted: Value = serde_json::from_str(CELERS_ACCEPTED).expect("json");
    let message = parse_python_message(accepted).expect("CeleRS' own envelope must parse");
    verify_message_format(&message).expect("CeleRS' own envelope is a valid v2 envelope");

    let body = EmbeddedBody::decode(&message.body).expect("body decodes");
    assert_eq!(body.args, vec![json!(4), json!(5)]);
    assert!(body.kwargs.is_empty());
    assert!(!body.embed.has_workflow());

    // The four workflow keys are present with explicit nulls, which is what
    // `as_task_v2` writes and what Celery's `Context` expects to `.get()`.
    let tuple: Value = serde_json::from_slice(&message.body).expect("body is json");
    for key in ["callbacks", "errbacks", "chain", "chord"] {
        assert_eq!(tuple[2][key], json!(null), "embed is missing {key}");
    }
}

// =============================================================================
// argsrepr / kwargsrepr
// =============================================================================

#[derive(serde::Deserialize)]
struct ReprTable {
    celery: String,
    args: Vec<ReprCase>,
    kwargs: Vec<ReprCase>,
}

#[derive(serde::Deserialize)]
struct ReprCase {
    value: Value,
    #[serde(rename = "repr")]
    expected: String,
}

fn repr_table() -> ReprTable {
    serde_json::from_str(SAFEREPR_TABLE).expect("the saferepr table is valid JSON")
}

/// Regression: `argsrepr` used to be `format!("{:?}", args)`, which renders
/// `serde_json::Value`'s Debug variants -- `add.delay(4, 5)` produced
/// `"[Number(4), Number(5)]"` where every Celery monitor, Flower included,
/// expects `"(4, 5)"`. `kwargsrepr` used `kwargs.to_string()`, i.e. JSON:
/// `{"debug":true}` instead of `{'debug': True}`.
#[test]
fn argsrepr_matches_celerys_own_saferepr() {
    let table = repr_table();
    assert!(
        !table.celery.is_empty(),
        "the table records its Celery version"
    );

    for case in &table.args {
        let args: Vec<Value> = case
            .value
            .as_array()
            .expect("each args case is a JSON array")
            .clone();
        assert_eq!(
            python_args_repr(&args),
            case.expected,
            "argsrepr for {} must match celery.utils.saferepr (celery {})",
            case.value,
            table.celery
        );
    }
}

#[test]
fn kwargsrepr_matches_celerys_own_saferepr() {
    let table = repr_table();
    for case in &table.kwargs {
        assert_eq!(
            python_kwargs_repr(&case.value),
            case.expected,
            "kwargsrepr for {} must match celery.utils.saferepr (celery {})",
            case.value,
            table.celery
        );
    }
}

/// The properties the table cannot state on its own, spelled out so a reader
/// knows they are intentional rather than accidental.
#[test]
fn the_repr_rules_are_the_python_ones_not_the_rust_ones() {
    // A one-element tuple keeps its trailing comma; an empty one is `()`.
    assert_eq!(python_args_repr(&[]), "()");
    assert_eq!(python_args_repr(&[json!(1)]), "(1,)");

    // Python literals, not JSON ones.
    assert_eq!(
        python_args_repr(&[json!(true), json!(false), json!(null)]),
        "(True, False, None)"
    );

    // Strings are single-quoted with `\'` escaping -- `saferepr`'s rule, not
    // the builtin `repr`'s, which would switch to double quotes here.
    assert_eq!(python_args_repr(&[json!("it's")]), "('it\\'s',)");

    // An integral float keeps its `.0`, or it would be indistinguishable from
    // an int in a monitor.
    assert_eq!(python_args_repr(&[json!(2.0)]), "(2.0,)");
    assert_eq!(python_args_repr(&[json!(2)]), "(2,)");

    // No Rust `Debug` anywhere.
    let rendered = python_args_repr(&[json!(4), json!("x"), json!({"a": 1})]);
    assert!(
        !rendered.contains("Number("),
        "Rust Debug leaked: {rendered}"
    );
    assert!(
        !rendered.contains("String("),
        "Rust Debug leaked: {rendered}"
    );
    assert!(
        !rendered.contains("Object("),
        "Rust Debug leaked: {rendered}"
    );
}

/// A dict is rendered with sorted keys because `serde_json::Map` is ordered.
/// Python reprs in insertion order, so the two can differ; the difference is
/// confined to a display header and is asserted here so it is a known,
/// documented property rather than a surprise.
#[test]
fn kwargsrepr_orders_keys_the_only_way_a_json_map_can() {
    assert_eq!(
        python_kwargs_repr(&json!({"z": 1, "a": 2})),
        "{'a': 2, 'z': 1}"
    );
}

/// `create_python_celery_message` must put those reprs in the headers, and
/// they must be the Python forms -- the header is the only place a monitor
/// looks.
#[test]
fn the_envelope_headers_carry_python_reprs() {
    let mut kwargs = HashMap::new();
    kwargs.insert("loud".to_string(), json!(true));
    kwargs.insert("punct".to_string(), json!("it's"));

    let envelope = create_python_celery_message(
        "tasks.greet",
        Uuid::nil(),
        vec![json!("Ada")],
        serde_json::to_value(&kwargs).expect("kwargs serialize"),
    )
    .expect("envelope serializes");

    assert_eq!(envelope["headers"]["argsrepr"], json!("('Ada',)"));
    assert_eq!(
        envelope["headers"]["kwargsrepr"],
        json!("{'loud': True, 'punct': 'it\\'s'}")
    );
}
